import{_ as a,o as s,c as r,a3 as e}from"./chunks/framework.Cc-oPviL.js";const g=JSON.parse('{"title":"04 · 评估与常见坑：RAG 为什么答不好","description":"","frontmatter":{},"headers":[],"relativePath":"ai/rag/04.md","filePath":"ai/rag/04.md"}'),l={name:"ai/rag/04.md"};function o(d,t,n,i,h,c){return s(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="_04-·-评估与常见坑-rag-为什么答不好" tabindex="-1">04 · 评估与常见坑：RAG 为什么答不好 <a class="header-anchor" href="#_04-·-评估与常见坑-rag-为什么答不好" aria-label="Permalink to &quot;04 · 评估与常见坑：RAG 为什么答不好&quot;">​</a></h1><blockquote><p><strong>学完你能说出</strong>：</p><ul><li>RAG 要分两段评估：检索得准不准、回答得好不好，各看什么指标。</li><li>答错了怎么一步步排查：先查资料在不在 → 再查检索到没到 → 最后查模型用没用对。</li><li>5 个常见的坑和对应的解决办法。</li></ul></blockquote><h2 id="先看地图" tabindex="-1">先看地图 <a class="header-anchor" href="#先看地图" aria-label="Permalink to &quot;先看地图&quot;">​</a></h2><p>RAG 模块的最后一篇。前面讲了怎么搭（01–03），这里讲<strong>怎么判断搭得好不好，坏了怎么修</strong>。面试里「你的 RAG 效果怎么评估」几乎必问。</p><p>本篇讲 3 个点：① 评估分两段 → ② 排查顺序 → ③ 常见的坑。</p><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p><strong>RAG 答不好，要么是没找到（检索问题），要么是找到了没用好（生成问题）。评估和排查都要把这两段分开看。</strong></p><h2 id="生活类比-学生考试答错了" tabindex="-1">生活类比：学生考试答错了 <a class="header-anchor" href="#生活类比-学生考试答错了" aria-label="Permalink to &quot;生活类比：学生考试答错了&quot;">​</a></h2><p>学生答错一道开卷题，原因可能是：</p><ol><li><strong>书里根本没有</strong>这个知识点（资料缺失）；</li><li>书里有，但<strong>没翻到那一页</strong>（检索失败）；</li><li>翻到了，但<strong>看错了、或者没照着写</strong>（生成失败）。</li></ol><p>三种原因的补救办法完全不同：补教材、教他查目录、教他认真读题。<strong>先定位原因，再对症下药。</strong></p><h2 id="一步步看" tabindex="-1">一步步看 <a class="header-anchor" href="#一步步看" aria-label="Permalink to &quot;一步步看&quot;">​</a></h2><h3 id="_1-先准备一套测试题" tabindex="-1">1. 先准备一套测试题 <a class="header-anchor" href="#_1-先准备一套测试题" aria-label="Permalink to &quot;1. 先准备一套测试题&quot;">​</a></h3><p>评估的前提是有一份<strong>测试集</strong>：比如 50 个真实问题，每题标好「标准答案」和「答案在哪一块」。没有测试集，所有「效果变好了」都是凭感觉。</p><h3 id="_2-检索阶段-看找没找到" tabindex="-1">2. 检索阶段：看找没找到 <a class="header-anchor" href="#_2-检索阶段-看找没找到" aria-label="Permalink to &quot;2. 检索阶段：看找没找到&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>意思</th><th>例子</th></tr></thead><tbody><tr><td><strong>命中率 / 召回率@K</strong></td><td>正确的那块是否出现在前 K 条里</td><td>50 题里有 40 题，正确块进了前 5 → 召回率@5 = 80%</td></tr><tr><td><strong>MRR（平均倒数排名）</strong></td><td>正确块排第几：第 1 名得 1 分，第 2 名得 1/2，第 3 名得 1/3…… 再取平均</td><td>排得越靠前，分越高</td></tr></tbody></table><h3 id="_3-生成阶段-看用没用好" tabindex="-1">3. 生成阶段：看用没用好 <a class="header-anchor" href="#_3-生成阶段-看用没用好" aria-label="Permalink to &quot;3. 生成阶段：看用没用好&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>问的是</th><th>例子</th></tr></thead><tbody><tr><td><strong>忠实度（Faithfulness）</strong></td><td>回答里的每句话，资料里都有依据吗？</td><td>资料写 5 天，回答写 7 天 → 不忠实</td></tr><tr><td><strong>答案相关性</strong></td><td>回答的是用户问的问题吗？</td><td>问年假，答了病假 → 不相关</td></tr><tr><td><strong>正确性</strong></td><td>和标准答案一致吗？</td><td>需要标准答案</td></tr></tbody></table><p>这些可以人工打分，也可以让另一个大模型当裁判打分（LLM-as-a-Judge），但裁判模型也会出错，要抽查。</p><h3 id="_4-排查顺序-从前往后-一段一段排除" tabindex="-1">4. 排查顺序：从前往后，一段一段排除 <a class="header-anchor" href="#_4-排查顺序-从前往后-一段一段排除" aria-label="Permalink to &quot;4. 排查顺序：从前往后，一段一段排除&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>答错了</span></span>
<span class="line"><span>  ↓ ① 资料库里有这个答案吗？        没有 → 补资料</span></span>
<span class="line"><span>  ↓ ② 正确的块被检索到了吗？        没有 → 调切块 / 混合检索 / 改写问题</span></span>
<span class="line"><span>  ↓ ③ 检索到了，排在前 K 里吗？      没有 → 加重排 / 调 K</span></span>
<span class="line"><span>  ↓ ④ 给了模型，它答对了吗？        没有 → 改提示词 / 换模型</span></span></code></pre></div><p><strong>一定从前往后查</strong>：资料都没有，调提示词是白费功夫。</p><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="为什么检索和生成要分开评估" tabindex="-1">为什么检索和生成要分开评估？ <a class="header-anchor" href="#为什么检索和生成要分开评估" aria-label="Permalink to &quot;为什么检索和生成要分开评估？&quot;">​</a></h3><ul><li><strong>问题</strong>：只看最终答案对不对，答错了不知道是「没找到」还是「没用好」，只能乱调。</li><li><strong>方案</strong>：检索看召回率、MRR；生成看忠实度、相关性。</li><li><strong>好处</strong>：一眼看出问题出在哪一段，改动有的放矢。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>RAG 是「检索 + 生成」两段，只看最终结果无法定位问题；分段评估，才能知道该优化检索还是生成。</p></div><h3 id="为什么特别看重「忠实度」" tabindex="-1">为什么特别看重「忠实度」？ <a class="header-anchor" href="#为什么特别看重「忠实度」" aria-label="Permalink to &quot;为什么特别看重「忠实度」？&quot;">​</a></h3><ul><li><strong>问题</strong>：RAG 的卖点是「有依据」。模型在资料之外自由发挥，即使碰巧答对，也失去了可信度。</li><li><strong>方案</strong>：逐句检查回答能否在资料里找到依据。</li><li><strong>好处</strong>：衡量的正是 RAG 最核心的价值：不编。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>RAG 的价值是答案有据可查，忠实度衡量的就是「有没有编」；不忠实的回答即使碰巧对，也不可靠。</p></div><h2 id="_5-个常见的坑" tabindex="-1">5 个常见的坑 <a class="header-anchor" href="#_5-个常见的坑" aria-label="Permalink to &quot;5 个常见的坑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>坑</th><th>表现</th><th>解决</th></tr></thead><tbody><tr><td><strong>解析质量差</strong></td><td>PDF 乱码、表格错位，检索结果读不懂</td><td>换解析工具；表格单独处理</td></tr><tr><td><strong>切块切断关键信息</strong></td><td>「入职满一年」和「5 天」被分到两块</td><td>按结构切、加重叠（见 <a href="/study-hub/ai/rag/02">02</a>）</td></tr><tr><td><strong>问题和文档说法不一样</strong></td><td>用户说「请假」，文档写「休假申请」；或者问题太口语</td><td>混合检索；用模型先<strong>改写问题</strong>再检索</td></tr><tr><td><strong>多块资料互相矛盾</strong></td><td>新旧两版制度都被检索到</td><td>元数据过滤（只要最新版）；按时间优先</td></tr><tr><td><strong>问题需要综合很多块</strong></td><td>「各部门年假规定有什么不同」</td><td>加大 K、分步检索，或先拆成子问题（Agent 的思路）</td></tr></tbody></table><h2 id="英文术语拆解" tabindex="-1">英文术语拆解 <a class="header-anchor" href="#英文术语拆解" aria-label="Permalink to &quot;英文术语拆解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>拆开看</th><th>一句话意思</th></tr></thead><tbody><tr><td>Evaluation</td><td>e 出 + value 价值 + -ation</td><td>评估</td></tr><tr><td>Test Set</td><td>test 测试 + set 集合</td><td>测试集：带标准答案的问题集合</td></tr><tr><td>Recall@K</td><td>recall 召回 + at K</td><td>前 K 条里有没有正确答案</td></tr><tr><td>MRR</td><td>Mean 平均 + Reciprocal 倒数 + Rank 排名</td><td>正确答案名次倒数的平均值</td></tr><tr><td>Faithfulness</td><td>faithful 忠实的 + -ness</td><td>忠实度：回答是否都有资料依据</td></tr><tr><td>LLM-as-a-Judge</td><td>大模型 + as 作为 + judge 裁判</td><td>让大模型给回答打分</td></tr><tr><td>Query Rewriting</td><td>query 查询 + rewriting 改写</td><td>检索前先把问题改写得更清楚</td></tr></tbody></table><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：你的 RAG 项目怎么评估效果？</strong></p><blockquote><p>先构建测试集（真实问题 + 标准答案 + 相关文档块）。检索层看 Recall@K 和 MRR，生成层看忠实度、答案相关性和正确性；可以人工评，也可以用 LLM 当裁判再抽检。每次改动（换切块、换模型、加重排）都跑同一个测试集对比。</p></blockquote><p><strong>Q：RAG 回答不准，你怎么排查？</strong></p><blockquote><p>从前往后：先确认知识库里有答案；再看正确的块有没有被检索到、排名如何；最后看模型拿到正确资料后有没有答对。分别对应补资料、优化切块和检索（混合检索、重排、问题改写）、优化提示词或模型。</p></blockquote><p><strong>Q：检索到的资料相互矛盾怎么办？</strong></p><blockquote><p>入库时带上版本、日期等元数据，检索时过滤或按时间排序；提示词里要求模型以最新资料为准，并在有冲突时明确指出。</p></blockquote><h2 id="容易混的地方" tabindex="-1">容易混的地方 <a class="header-anchor" href="#容易混的地方" aria-label="Permalink to &quot;容易混的地方&quot;">​</a></h2><ul><li><strong>答对了 ≠ 系统好</strong>：碰巧答对、但资料里没有依据的回答，换个问题就会出错。</li><li><strong>一次测试不算数</strong>：要有固定的测试集，每次改动都在同一批题上对比。</li><li><strong>大模型裁判不是标准答案</strong>：LLM-as-a-Judge 会有偏差，要抽查。</li></ul><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>← 来自</strong> <a href="/study-hub/ai/rag/02">切块与入库</a>、<a href="/study-hub/ai/rag/03">检索与重排</a>：排查时对应前两段。</li><li><strong>→ 影响</strong> <a href="/study-hub/ai/agent/05">Agent 安全与评估</a>：Agent 的评估是同样的思路，只是步骤更多。</li><li><strong>类比</strong> <a href="/study-hub/bagu/db/05">SQL 执行与优化</a>：都是「先定位慢 / 错在哪一步，再针对性优化」。</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：RAG 答错的三类原因是什么？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>① 资料库里没有答案；② 有答案但没检索到（或排名太靠后）；③ 检索到了但模型没用好。分别对应：补资料、优化检索、优化提示词或模型。</p></details><p><strong>Q2：50 个测试问题中，有 40 个的正确块出现在前 5 条里，召回率@5 是多少？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>40 / 50 = <strong>80%</strong>。</p></details><p><strong>Q3：什么是忠实度？为什么它对 RAG 特别重要？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>回答里的每句话是否都能在给定资料里找到依据。RAG 的核心价值就是「有据可查、不编」，所以忠实度衡量的正是 RAG 最重要的能力。</p></details><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能用「学生开卷答错」类比，说出 RAG 答错的三类原因</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能说出检索阶段的 2 个指标、生成阶段的 2 个指标，并能算召回率@K</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能按「资料 → 检索 → 排名 → 生成」的顺序讲出排查流程</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能说出 5 个常见坑中的至少 3 个及其解决办法</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能说清为什么评估必须有固定的测试集</li></ul><h2 id="下一步该懂什么" tabindex="-1">下一步该懂什么 <a class="header-anchor" href="#下一步该懂什么" aria-label="Permalink to &quot;下一步该懂什么&quot;">​</a></h2><ul><li>RAG 只会「查完再答」。要让 AI 自己决定查什么、查几次、还能调用其他工具？→ <a href="/study-hub/ai/agent/01">Agent 是什么</a></li></ul>`,55)])])}const p=a(l,[["render",o]]);export{g as __pageData,p as default};
